const req = $input.first().json;
const secret = req.headers && req.headers['x-webhook-secret'];
if (!secret || secret !== $env.WEBHOOK_SECRET) return [];
const body = req.body || {};
const rec = body.record;
if (body.type !== 'INSERT' || !rec || !rec.id) return [];
return [{ json: { event_id: rec.id } }];

const d = $input.first().json;
if (!d || !d.shipment || !d.shipment.client_phone || !d.forwarder || !d.forwarder.phone_number_id) return [];
const labels = {
  enregistre: `Colis enregistré`,
  recu_entrepot: `Colis reçu à l'entrepôt en Chine`,
  groupage: `Colis intégré au groupage`,
  expedie: `Conteneur expédié`,
  en_transit: `En transit maritime`,
  arrive_port: `Arrivé au port de destination`,
  dedouanement: `En cours de dédouanement`,
  disponible: `Disponible au retrait`,
  livre: `Livré`
};
let to = String(d.shipment.client_phone).replace(/\D/g, '');
if (to.startsWith('00')) to = to.slice(2);
const label = labels[d.event.status] || d.event.status;
const link = `${$env.TRACKING_BASE_URL}?code=${d.shipment.tracking_code}`;
return [{ json: {
  to,
  phone_number_id: d.forwarder.phone_number_id,
  wa_token: d.forwarder.wa_token || $env.WA_TOKEN,
  template: $env.WA_TEMPLATE_TRACKING || 'suivi_colis',
  params: [d.shipment.client_name, label, d.shipment.tracking_code, link],
  event_id: d.event.id
} }];
